Lemma firstn4_le8 : forall w : word, firstn 4 (le8 w) = le4 w.
Proof. ltac2:(Rpl.RP.run_i (rplG ()) 0 "S10|30;$w;R!1+0!1,1|600;!2,^7!1+4!1+0!1,10!1'^8#1").
Qed.

